using FiveSmartFarmCreators.Ichu.Platform.OperationsMonitoring.Domain.Model.ValueObjects;

namespace FiveSmartFarmCreators.Ichu.Platform.OperationsMonitoring.Domain.Model.Aggregates;

/// <summary>
///     Aggregate root representing a reading captured by a cattle band and relayed by an Edge Gateway. Its identity is
///     the device identifier together with the reading identifier generated by the firmware, which never changes
///     across retries.
/// </summary>
public sealed class TelemetryReading
{
    /// <summary>Age after which a reading is reported with its age and never presented as current.</summary>
    public static readonly TimeSpan StalenessLimit = TimeSpan.FromHours(24);

    private TelemetryReading()
    {
    }

    /// <summary>
    ///     Initializes a new instance of the <see cref="TelemetryReading"/> class.
    /// </summary>
    /// <param name="readingId">The reading identifier generated by the device firmware.</param>
    /// <param name="deviceId">The device that captured the reading.</param>
    /// <param name="recordedAt">The instant the device captured the reading.</param>
    /// <param name="bodyTemperature">The captured body temperature in degrees Celsius.</param>
    /// <param name="activityIndex">The captured activity index.</param>
    /// <param name="ruminationMinutes">The captured rumination minutes.</param>
    /// <param name="batteryPercent">The captured battery level in percent.</param>
    /// <param name="position">The captured GPS position.</param>
    /// <param name="gatewayId">The Edge Gateway that relayed the reading.</param>
    /// <param name="ranchId">The ranch that owns the device.</param>
    /// <param name="cattleId">The animal assigned to the device at the capture time, if any.</param>
    /// <param name="receivedAt">The instant the cloud received the reading.</param>
    /// <exception cref="ArgumentException">Thrown when an identifier is empty or a captured value is out of its domain.</exception>
    public TelemetryReading(
        Guid readingId,
        Guid deviceId,
        DateTimeOffset recordedAt,
        Measurement bodyTemperature,
        Measurement activityIndex,
        Measurement ruminationMinutes,
        Measurement batteryPercent,
        PositionMeasurement position,
        Guid gatewayId,
        Guid ranchId,
        Guid? cattleId,
        DateTimeOffset receivedAt)
    {
        if (readingId == Guid.Empty || deviceId == Guid.Empty || gatewayId == Guid.Empty || ranchId == Guid.Empty)
        {
            throw new ArgumentException("Reading, device, gateway and ranch identifiers are required.");
        }

        if (cattleId == Guid.Empty)
        {
            throw new ArgumentException("An attributed cattle identifier cannot be empty.");
        }

        EnsureNonNegative(activityIndex, "Activity index");
        EnsureNonNegative(ruminationMinutes, "Rumination minutes");
        if (batteryPercent.Value is < 0 or > 100)
        {
            throw new ArgumentException("Battery level must be between 0 and 100 percent.");
        }

        Id = Guid.NewGuid();
        ReadingId = readingId;
        DeviceId = deviceId;
        RecordedAt = MonitoringTime.Normalize(recordedAt);
        BodyTemperature = bodyTemperature;
        ActivityIndex = activityIndex;
        RuminationMinutes = ruminationMinutes;
        BatteryPercent = batteryPercent;
        Position = position;
        GatewayId = gatewayId;
        RanchId = ranchId;
        CattleId = cattleId;
        ReceivedAt = MonitoringTime.Normalize(receivedAt);
    }

    /// <summary>Gets the internal identifier of the stored reading.</summary>
    public Guid Id { get; private set; }

    /// <summary>Gets the reading identifier generated by the device firmware.</summary>
    public Guid ReadingId { get; private set; }

    /// <summary>Gets the device that captured the reading.</summary>
    public Guid DeviceId { get; private set; }

    /// <summary>Gets the Edge Gateway that relayed the reading.</summary>
    public Guid GatewayId { get; private set; }

    /// <summary>Gets the ranch that owns the device.</summary>
    public Guid RanchId { get; private set; }

    /// <summary>Gets the animal assigned to the device at the capture time, or <see langword="null"/> when none was.</summary>
    public Guid? CattleId { get; private set; }

    /// <summary>Gets the instant the device captured the reading.</summary>
    public DateTimeOffset RecordedAt { get; private set; }

    /// <summary>Gets the instant the cloud received the reading.</summary>
    public DateTimeOffset ReceivedAt { get; private set; }

    /// <summary>Gets the captured body temperature in degrees Celsius.</summary>
    public Measurement BodyTemperature { get; private set; } = Measurement.Absent();

    /// <summary>Gets the captured activity index.</summary>
    public Measurement ActivityIndex { get; private set; } = Measurement.Absent();

    /// <summary>Gets the captured rumination minutes.</summary>
    public Measurement RuminationMinutes { get; private set; } = Measurement.Absent();

    /// <summary>Gets the captured battery level in percent.</summary>
    public Measurement BatteryPercent { get; private set; } = Measurement.Absent();

    /// <summary>Gets the captured GPS position.</summary>
    public PositionMeasurement Position { get; private set; } = PositionMeasurement.Absent();

    /// <summary>
    ///     Determines whether the reading is too old to be presented as current.
    /// </summary>
    /// <param name="now">The instant used to evaluate the age.</param>
    /// <returns><see langword="true"/> when the capture is older than <see cref="StalenessLimit"/>.</returns>
    public bool IsStale(DateTimeOffset now) => now - RecordedAt > StalenessLimit;

    /// <summary>
    ///     Gets the measurement of a metric that can be evaluated against a threshold.
    /// </summary>
    /// <param name="metric">The monitored metric.</param>
    /// <returns>The captured measurement of the metric.</returns>
    public Measurement MeasurementOf(MonitoredMetric metric) => metric switch
    {
        MonitoredMetric.BodyTemperature => BodyTemperature,
        MonitoredMetric.ActivityIndex => ActivityIndex,
        _ => throw new ArgumentOutOfRangeException(nameof(metric), metric, null)
    };

    /// <summary>
    ///     Determines whether another reading carries the same captured content. The relaying gateway and the
    ///     reception time are not part of the captured content.
    /// </summary>
    /// <param name="other">The reading to compare with.</param>
    /// <returns><see langword="true"/> when both readings were captured identically.</returns>
    public bool HasSameCaptureAs(TelemetryReading other) =>
        ReadingId == other.ReadingId &&
        DeviceId == other.DeviceId &&
        RecordedAt == other.RecordedAt &&
        BodyTemperature == other.BodyTemperature &&
        ActivityIndex == other.ActivityIndex &&
        RuminationMinutes == other.RuminationMinutes &&
        BatteryPercent == other.BatteryPercent &&
        Position == other.Position;

    private static void EnsureNonNegative(Measurement measurement, string name)
    {
        if (measurement.Value < 0)
        {
            throw new ArgumentException($"{name} cannot be negative.");
        }
    }
}
